package kr.jinsu.radio;
import org.json.*;
import org.junit.*;
import static org.junit.Assert.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.atomic.AtomicInteger;

public class LiveFailureTest {
 JSONObject fixture(String label)throws Exception{try(InputStream in=getClass().getResourceAsStream("/youtube/"+label+".json")){assertNotNull(in);return new JSONObject(new String(in.readAllBytes(),StandardCharsets.UTF_8));}}
 String page(JSONObject p){return "ytInitialPlayerResponse = "+p+"; \"VISITOR_DATA\":\"visitor-test\"; \"STS\":123;";}
 void expectState(YoutubeLiveAudio.LiveState expected,JSONObject p)throws Exception{assertEquals(expected,YoutubeLiveAudio.liveState(p));}
 @Test public void capturedPublicResponsesSeparateArchiveLiveAndOrdinaryVideo()throws Exception{expectState(YoutubeLiveAudio.LiveState.ENDED,fixture("archive"));expectState(YoutubeLiveAudio.LiveState.LIVE,fixture("current"));expectState(YoutubeLiveAudio.LiveState.NOT_LIVE,fixture("ordinary"));assertFalse(fixture("archive").getJSONObject("videoDetails").has("isLive"));}
 @Test public void missingLiveFlagOrOfflineStateNeverMeansEnded()throws Exception{JSONObject p=fixture("current");p.getJSONObject("videoDetails").remove("isLive");p.remove("microformat");expectState(YoutubeLiveAudio.LiveState.UNKNOWN,p);p.getJSONObject("playabilityStatus").put("status","LIVE_STREAM_OFFLINE");expectState(YoutubeLiveAudio.LiveState.UNKNOWN,p);expectState(YoutubeLiveAudio.LiveState.UNKNOWN,new JSONObject());}
 @Test public void upcomingPrivateAndMalformedEndAreNotEnded()throws Exception{JSONObject p=fixture("archive");p.getJSONObject("playabilityStatus").put("status","LOGIN_REQUIRED");expectState(YoutubeLiveAudio.LiveState.UNKNOWN,p);p.getJSONObject("playabilityStatus").put("status","LIVE_STREAM_OFFLINE");p.getJSONObject("videoDetails").put("isUpcoming",true);expectState(YoutubeLiveAudio.LiveState.UPCOMING,p);p=fixture("archive");p.getJSONObject("microformat").getJSONObject("playerMicroformatRenderer").getJSONObject("liveBroadcastDetails").put("endTimestamp","bad-time");expectState(YoutubeLiveAudio.LiveState.UNKNOWN,p);p.getJSONObject("microformat").getJSONObject("playerMicroformatRenderer").getJSONObject("liveBroadcastDetails").put("endTimestamp","2999-01-01T00:00:00Z");expectState(YoutubeLiveAudio.LiveState.UNKNOWN,p);}
 @Test public void explicitCurrentLiveWinsOverStaleEndMetadata()throws Exception{JSONObject p=fixture("archive");p.getJSONObject("videoDetails").put("isLive",true);expectState(YoutubeLiveAudio.LiveState.LIVE,p);}
 @Test public void endedBroadcastStopsBeforePlayerApiAndNeverSearchesChannel()throws Exception{JSONObject p=fixture("archive");AtomicInteger requests=new AtomicInteger();try{YoutubeLiveAudio.resolve("CMLD0Lp0JBg","UCLA_DiR1FfKNvjuUpBHmylQ",(url,body,visitor)->{requests.incrementAndGet();assertEquals("https://www.youtube.com/watch?v=CMLD0Lp0JBg",url);return page(p);});fail();}catch(YoutubeLiveAudio.LiveUnavailableException ended){assertEquals(YoutubeLiveAudio.LiveState.ENDED,ended.state);}assertEquals(1,requests.get());}
 @Test public void networkFailureDoesNotProbeOtherBroadcasts()throws Exception{AtomicInteger requests=new AtomicInteger();try{YoutubeLiveAudio.resolve("6QZ_qc75ihU",YoutubeLiveAudio.CHANNEL_ID,(url,body,visitor)->{requests.incrementAndGet();throw new IOException("offline");});fail();}catch(IOException expected){assertFalse(expected instanceof YoutubeLiveAudio.LiveUnavailableException);}assertEquals(1,requests.get());}
 @Test public void sameChannelDifferentInitialVideoIsRejectedBeforeAnyPlayback()throws Exception{JSONObject p=fixture("current");p.getJSONObject("videoDetails").put("videoId","abcdefghijk");AtomicInteger requests=new AtomicInteger();try{YoutubeLiveAudio.resolve("6QZ_qc75ihU",YoutubeLiveAudio.CHANNEL_ID,(u,b,v)->{requests.incrementAndGet();return page(p);});fail();}catch(IOException mismatch){assertFalse(mismatch instanceof YoutubeLiveAudio.LiveUnavailableException);}assertEquals(1,requests.get());}
 @Test public void sameChannelDifferentApiVideoIsRejectedWithoutAudioRequest()throws Exception{JSONObject p=fixture("current"),changed=fixture("current");changed.getJSONObject("videoDetails").put("videoId","abcdefghijk");AtomicInteger requests=new AtomicInteger();try{YoutubeLiveAudio.resolve("6QZ_qc75ihU",YoutubeLiveAudio.CHANNEL_ID,(u,b,v)->{requests.incrementAndGet();return b==null?page(p):changed.toString();});fail();}catch(IOException mismatch){assertFalse(mismatch instanceof YoutubeLiveAudio.LiveUnavailableException);}assertEquals(2,requests.get());}
 @Test public void endingBetweenPageAndApiIsReportedForSameVideoOnly()throws Exception{JSONObject p=fixture("current"),ended=fixture("archive");ended.getJSONObject("videoDetails").put("videoId","6QZ_qc75ihU").put("channelId",YoutubeLiveAudio.CHANNEL_ID);AtomicInteger requests=new AtomicInteger();try{YoutubeLiveAudio.resolve("6QZ_qc75ihU",YoutubeLiveAudio.CHANNEL_ID,(u,b,v)->{requests.incrementAndGet();return b==null?page(p):ended.toString();});fail();}catch(YoutubeLiveAudio.LiveUnavailableException expected){assertEquals(YoutubeLiveAudio.LiveState.ENDED,expected.state);}assertEquals(2,requests.get());}
 @Test public void pinnedLiveStillResolvesAudioAndKeepsPublicRequestContext()throws Exception{JSONObject p=fixture("current"),api=fixture("current");api.put("streamingData",new JSONObject().put("hlsManifestUrl","https://manifest.googlevideo.com/master.m3u8"));AtomicInteger requests=new AtomicInteger();String url=YoutubeLiveAudio.resolve("6QZ_qc75ihU",YoutubeLiveAudio.CHANNEL_ID,(u,b,v)->{requests.incrementAndGet();assertFalse(u.contains("/channel/"));if(b!=null){JSONObject body=new JSONObject(b);assertEquals("6QZ_qc75ihU",body.getString("videoId"));assertEquals(123,body.getJSONObject("playbackContext").getJSONObject("contentPlaybackContext").getInt("signatureTimestamp"));assertEquals("visitor-test",v);return api.toString();}return u.contains("googlevideo.com")?YoutubeLiveAudioTest.AUDIO:page(p);});assertEquals("https://manifest.googlevideo.com/audio-high.m3u8",url);assertEquals(3,requests.get());}
 @Test public void wrongChannelCannotBeUsedAsEvidenceOfEnded()throws Exception{JSONObject p=fixture("archive");try{YoutubeLiveAudio.validateIdentity(p,YoutubeLiveAudio.CHANNEL_ID,"CMLD0Lp0JBg");fail();}catch(IOException expected){}}
}
